(()=>{const reduce=matchMedia('(prefers-reduced-motion:reduce)').matches,b=document.body,s=document.createElement('style');s.textContent=`body{background:radial-gradient(circle at 50% 8%,#321725 0,#110a10 38%,#070609 100%)}body:before{content:'';position:fixed;inset:0;pointer-events:none;z-index:-2;background:radial-gradient(circle at 50% 35%,#e6b1c012,transparent 42%),linear-gradient(120deg,transparent 30%,#d8ac8808 50%,transparent 70%)}.fxbar{position:fixed;top:0;left:0;width:100%;height:2px;background:#fff1;z-index:100}.fxbar i{display:block;height:100%;width:0;background:#e6b1c0;box-shadow:0 0 18px #e6b1c0}.fx-orb{position:fixed;border-radius:50%;pointer-events:none;filter:blur(90px);opacity:.13;z-index:-1}.fx-orb.a{width:380px;height:380px;left:-160px;top:18%;background:#b94d72;animation:drift 16s ease-in-out infinite}.fx-orb.b{width:320px;height:320px;right:-130px;bottom:10%;background:#d8ac88;animation:drift 19s ease-in-out infinite reverse}.fx-petal{position:fixed;top:-10vh;pointer-events:none;z-index:2;width:12px;height:18px;background:linear-gradient(135deg,#f2b8c9,#9d526d);border-radius:100% 0 100% 0;opacity:0;filter:drop-shadow(0 0 5px #e6b1c055);animation:petal linear infinite}.fx-mote{position:fixed;width:3px;height:3px;border-radius:50%;background:#ffe7ee;box-shadow:0 0 12px #e6b1c0;pointer-events:none;opacity:0;animation:mote ease-in-out infinite}.fxr{opacity:0;transform:translateY(40px);transition:1.05s cubic-bezier(.2,.8,.2,1)}.fxr.on{opacity:1;transform:none}.proposal-accepted:after{content:'♡';position:fixed;inset:0;display:grid;place-items:center;z-index:80;pointer-events:none;font-size:min(35vw,240px);color:#e6b1c0;text-shadow:0 0 50px #fff;animation:accept .9s ease both}@keyframes petal{0%{transform:translate3d(0,-10vh,0) rotate(0);opacity:0}12%{opacity:.7}50%{transform:translate3d(80px,55vh,0) rotate(180deg)}100%{transform:translate3d(-80px,120vh,0) rotate(420deg);opacity:0}}@keyframes mote{0%,100%{transform:translate3d(0,20px,0);opacity:0}35%{opacity:.65}65%{transform:translate3d(25px,-80px,0);opacity:.25}}@keyframes drift{50%{transform:translate(80px,-45px)}}@keyframes accept{0%{opacity:0;transform:scale(.5)}45%{opacity:1;transform:scale(1.12)}100%{opacity:0;transform:scale(1.4)}}@media(prefers-reduced-motion:reduce){.fx-petal,.fx-mote{display:none}}`;b.appendChild(s);const bar=document.createElement('div');bar.className='fxbar';bar.innerHTML='<i></i>';b.appendChild(bar);['a','b'].forEach(c=>{const o=document.createElement('div');o.className='fx-orb '+c;b.appendChild(o)});if(!reduce){for(let i=0;i<18;i++){const p=document.createElement('i');p.className='fx-petal';p.style.left=Math.random()*100+'%';p.style.animationDuration=8+Math.random()*9+'s';p.style.animationDelay=-Math.random()*14+'s';p.style.transform=`scale(${.55+Math.random()*.8})`;b.appendChild(p)}for(let i=0;i<28;i++){const m=document.createElement('i');m.className='fx-mote';m.style.left=Math.random()*100+'%';m.style.top=25+Math.random()*70+'%';m.style.animationDuration=5+Math.random()*6+'s';m.style.animationDelay=-Math.random()*7+'s';b.appendChild(m)}}document.querySelectorAll('section').forEach(e=>e.classList.add('fxr'));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('on');io.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.fxr').forEach(e=>io.observe(e));addEventListener('scroll',()=>{const m=document.documentElement.scrollHeight-innerHeight;bar.firstElementChild.style.width=(m?scrollY/m*100:0)+'%'})})();